catalog_script_client.script:
function onLoad() {

    // Hide all conditional fields by default on form load
    // These will only appear when the user makes the relevant selections
    g_form.setVisible('requires_monitor', false);
    g_form.setVisible('monitor_quantity', false);
    g_form.setVisible('specific_address', false);
    g_form.setVisible('old_asset_tag', false);

    // Hide asset_tag and configuration_notes on the user request form
    // These should only be visible on catalog tasks for fulfillers to fill in before closing

    var isTask = g_form.getTableName() === 'sc_task';
    if (!isTask) {
        g_form.setVisible('asset_tag', false);
        g_form.setVisible('configuration_notes', false);
    }

    // Clear all pre-filled values so the form starts completely blank
    g_form.setValue('work_setup', '');
    g_form.setValue('device_type', '');
    g_form.setValue('delivery_location', '');
    g_form.setValue('department', '');
    g_form.setValue('operating_system', '');
    g_form.setValue('requires_monitor', false);
    g_form.setValue('is_replacement', '');
}
